package com.jumblemint.cows.ui.components

import androidx.compose.animation.core.animateFloatAsState
import androidx.compose.foundation.background
import androidx.compose.foundation.layout.Box
import androidx.compose.foundation.layout.fillMaxSize
import androidx.compose.foundation.layout.padding
import androidx.compose.material.DismissDirection
import androidx.compose.material.DismissValue
import androidx.compose.material.ExperimentalMaterialApi
import androidx.compose.material.SwipeToDismiss
import androidx.compose.material.rememberDismissState
import androidx.compose.material3.Icon
import androidx.compose.material3.MaterialTheme
import androidx.compose.material3.icons.Icons
import androidx.compose.material3.icons.filled.Delete
import androidx.compose.runtime.Composable
import androidx.compose.runtime.getValue
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.draw.scale
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.semantics.semantics
import androidx.compose.ui.semantics.testTag
import androidx.compose.ui.unit.dp

/**
 * Generic swipe-to-delete container with red background and trash icon.
 * Calls onDelete when fully dismissed in either direction.
 */
@OptIn(ExperimentalMaterialApi::class)
@Composable
fun <T> SwipeToDeleteContainer(
    item: T,
    modifier: Modifier = Modifier,
    enabled: Boolean = true,
    onDelete: (T) -> Unit,
    content: @Composable () -> Unit
) {
    val haptics = androidx.compose.ui.platform.LocalHapticFeedback.current

    val dismissState = rememberDismissState(
        confirmStateChange = { value ->
            if (value == DismissValue.DismissedToStart || value == DismissValue.DismissedToEnd) {
                // Haptic feedback on successful swipe
                haptics.performHapticFeedback(androidx.compose.ui.hapticfeedback.HapticFeedbackType.LongPress)
                onDelete(item)
                true
            } else {
                true
            }
        }
    )

    val scale by animateFloatAsState(
        targetValue = if (dismissState.targetValue == DismissValue.Default) 0.8f else 1.2f,
        label = "icon-scale"
    )

    SwipeToDismiss(
        state = dismissState,
        directions = if (enabled) setOf(DismissDirection.StartToEnd, DismissDirection.EndToStart) else emptySet(),
        background = {
            val color = MaterialTheme.colorScheme.error
            Box(
                modifier = Modifier
                    .fillMaxSize()
                    .background(color)
                    .semantics { testTag = "swipe_delete_bg" },
                contentAlignment = Alignment.Center
            ) {
                Icon(
                    imageVector = Icons.Filled.Delete,
                    contentDescription = null,
                    tint = Color.White,
                    modifier = Modifier.scale(scale)
                )
            }
        },
        dismissContent = {
            Box(modifier = modifier.padding(vertical = 2.dp)) {
                content()
            }
        }
    )
}

